    v_topic_id UUID;
BEGIN
    -- Ensure Topic exists
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Reproductive Pathology', 'reproductive-pathology', 3, 2, 60)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- GESTATIONAL & PLACENTAL DISORDERS: EARLY PREGNANCY (241-260)
    (v_topic_id, '241. What is the most common cause of a spontaneous abortion (miscarriage) occurring in the first trimester (< 13 weeks)?', '["Maternal hypertension", "Chromosomal anomalies (e.g., Trisomy 16)", "Listeria monocytogenes infection", "Cervical incompetence"]', 1, 'Chromosomal errors (most commonly Trisomy 16, followed by Turner Syndrome 45,XO) account for roughly 50-60% of all early spontaneous abortions.'),
    (v_topic_id, '242. A 28-year-old female presents with lower abdominal pain and vaginal bleeding. She is 8 weeks pregnant. An ultrasound shows an empty uterus and a mass in the right adnexa. Diagnosis?', '["Appendicitis", "Ectopic Pregnancy", "Spontaneous Abortion", "Molar Pregnancy"]', 1, 'Implantation outside the uterine cavity is an ectopic pregnancy. The most common site (90%) is the ampulla of the fallopian tube.'),
    (v_topic_id, '243. What is the most significant risk factor for developing an ectopic pregnancy?', '["Previous C-section", "Scarring of the fallopian tube (e.g., from prior Pelvic Inflammatory Disease / Chlamydia)", "Obesity", "Use of oral contraceptives"]', 1, 'Tubal scarring prevents the fertilized egg from moving smoothly into the uterus, causing it to implant in the tube.'),
    (v_topic_id, '244. A ruptured ectopic pregnancy is a medical emergency because it causes massive intra-abdominal hemorrhage. What physical sign might this produce?', '["Pain radiating to the left shoulder (Kehr sign)", "Jaundice", "Bradycardia", "Severe headache"]', 0, 'Massive bleeding irritates the diaphragm, causing referred pain to the shoulder via the phrenic nerve (Kehr sign).'),
    (v_topic_id, '245. Ectopic pregnancy is often treated medically if unruptured and small. Which drug is used to destroy the rapidly dividing trophoblastic cells?', '["Penicillin", "Methotrexate", "Clomiphene", "Misoprostol"]', 1, 'Methotrexate (a folate antagonist) halts DNA synthesis in the rapidly dividing fetal/placental cells, causing the pregnancy to resorb safely without surgery.'),
    (v_topic_id, '246. Which teratogen classically causes severe limb defects (phocomelia/flipper limbs) if taken during early pregnancy?', '["Phenytoin", "Thalidomide", "Alcohol", "Warfarin"]', 1, 'Thalidomide, once used for morning sickness, causes catastrophic limb foreshortening.'),
    (v_topic_id, '247. Fetal Alcohol Syndrome is the most common preventable cause of intellectual disability in the US. What are the classic facial features?', '["Smooth philtrum, thin upper lip, and microcephaly", "Cleft palate and macroglossia", "Frontal bossing and saddle nose", "Slanted eyes and epicanthal folds"]', 0, 'Alcohol impairs cell migration in the brain and neural crest, leading to facial dysmorphology and cognitive deficits.'),
    (v_topic_id, '248. ACE inhibitors (like Lisinopril) are contraindicated in pregnancy because they cause?', '["Limb defects", "Fetal renal damage (renal dysgenesis/agenesis) leading to oligohydramnios", "Deafness", "Heart defects"]', 1, 'Fetal kidneys require Angiotensin II for normal development and blood flow. ACE inhibitors destroy the kidneys, leading to Potter Sequence (from lacking amniotic fluid).'),
    (v_topic_id, '249. Which anticonvulsant medication is associated with Fetal Hydantoin Syndrome (cleft lip/palate, microcephaly, nail hypoplasia)?', '["Valproate", "Carbamazepine", "Phenytoin", "Lamotrigine"]', 2, 'Phenytoin is a known teratogen. (Note: Valproate causes neural tube defects like spina bifida by interfering with folate absorption).'),
    (v_topic_id, '250. Placenta Previa occurs when the placenta implants over the cervical os. How does it classically present in the third trimester?', '["Severe, tearing abdominal pain", "Painless, bright red vaginal bleeding", "High blood pressure and seizures", "No symptoms until delivery"]', 1, 'As the lower uterus stretches in the 3rd trimester, the overlying placenta tears slightly, causing painless bleeding. Vaginal exams are absolutely contraindicated.'),
    (v_topic_id, '251. Placental Abruption is the premature separation of the placenta from the uterine wall before delivery. How does it present clinically?', '["Painless bleeding", "Painful, dark red vaginal bleeding with a rigid, board-like abdomen", "Massive proteinuria", "It is usually asymptomatic"]', 1, 'Blood accumulates behind the placenta, causing massive painful uterine contractions (rigid abdomen). It deprives the fetus of oxygen and can cause maternal DIC.'),
    (v_topic_id, '252. What are the major risk factors for Placental Abruption?', '["Prior C-section and multiparity", "Cocaine use, smoking, maternal hypertension, and trauma", "Diabetes and obesity", "Bed rest"]', 1, 'Anything that causes severe vasoconstriction (Cocaine, Hypertension, Smoking) or physical shear force (Trauma) can rip the placenta off the wall.'),
    (v_topic_id, '253. Placenta Accreta is a condition where the placenta attaches directly to the myometrium, bypassing the decidua basalis. What is the major risk during delivery?', '["Fetal hypoxia", "Massive, life-threatening postpartum hemorrhage because the placenta cannot cleanly separate", "Eclampsia", "Uterine inversion"]', 1, 'Because it is grown into the muscle, attempting to pull the placenta out after the baby is born causes catastrophic bleeding, often requiring an emergent hysterectomy.'),
    (v_topic_id, '254. What is the most significant risk factor for developing Placenta Accreta?', '["Prior C-section with Placenta Previa overlying the old scar", "Cocaine use", "Nulliparity", "Young maternal age"]', 0, 'A previous C-section scar lacks a normal decidual layer. If a new placenta implants over it (previa), the villi grow straight into the muscle (accreta).'),
    (v_topic_id, '255. Vasa Previa occurs when fetal blood vessels cross directly over the cervical os. What happens if these vessels rupture when the membranes break (water breaks)?', '["The mother bleeds to death", "Painless vaginal bleeding followed immediately by severe fetal bradycardia and death", "Severe maternal pain", "Nothing, it is benign"]', 1, 'The blood lost is purely FETAL blood. Since the fetus has very little blood volume, it rapidly bleeds out and dies if an emergency C-section is not performed instantly.'),
    (v_topic_id, '256. Monozygotic (Identical) twins result from the splitting of a single fertilized egg. If they split between days 4-8 (blastocyst stage), what kind of placenta and sac do they share?', '["Di-chorionic, Di-amniotic", "Mono-chorionic, Di-amniotic (One placenta, two inner sacs)", "Mono-chorionic, Mono-amniotic", "Conjoined twins"]', 1, 'Splitting at days 4-8 (most common) results in a shared placenta but separate amniotic sacs (MoDi).'),
    (v_topic_id, '257. What is Twin-Twin Transfusion Syndrome?', '["One twin steals nutrients from the mother", "Abnormal vascular anastomoses in a shared (monochorionic) placenta cause blood to be shunted from one twin (donor) to the other (recipient)", "Both twins become anemic", "Twins exchange immune cells"]', 1, 'The donor twin becomes severely anemic, oliguric (oligohydramnios), and growth-restricted. The recipient twin gets volume overloaded, polyuric (polyhydramnios), and goes into heart failure.'),
    (v_topic_id, '258. Polyhydramnios is an excess of amniotic fluid. What fetal anomaly commonly causes this?', '["Bilateral renal agenesis", "Anencephaly or esophageal atresia (inability to swallow the fluid)", "Posterior urethral valves", "Polycystic kidney disease"]', 1, 'Amniotic fluid is produced by fetal urine and swallowed by the fetus. If the fetus cannot swallow (GI blockage or severe brain defect), fluid builds up.'),
    (v_topic_id, '259. Oligohydramnios is too little amniotic fluid. What fetal anomaly commonly causes this?', '["Anencephaly", "Esophageal atresia", "Bilateral renal agenesis (inability to produce urine)", "Duodenal atresia"]', 2, 'If the fetus has no kidneys, it cannot urinate. Lack of fluid causes Potter Sequence (flat face, clubbed feet, pulmonary hypoplasia because fluid is needed to expand the lungs).'),
    (v_topic_id, '260. A baby with Potter Sequence typically dies shortly after birth from?', '["Renal failure", "Pulmonary hypoplasia (inability to breathe)", "Heart failure", "Sepsis"]', 1, 'Amniotic fluid is physically drawn into the fetal lungs and is required for them to expand and develop. Without fluid, the lungs remain tiny and non-functional.'),

    -- GESTATIONAL DISORDERS: PREECLAMPSIA & GTD (261-285)
    (v_topic_id, '261. Preeclampsia is a systemic disorder of pregnancy characterized by the new onset of which two clinical signs after 20 weeks of gestation?', '["Hypotension and bradycardia", "Hypertension and Proteinuria (or end-organ dysfunction)", "Seizures and coma", "Hyperglycemia and glycosuria"]', 1, 'Preeclampsia is >140/>90 BP with proteinuria (>300mg/24hr). If severe, it involves headache, visual changes, or elevated liver enzymes.'),
    (v_topic_id, '262. What is the fundamental pathophysiology underlying Preeclampsia?', '["Bacterial infection of the placenta", "Abnormal invasion of trophoblasts into the maternal spiral arteries, leading to placental ischemia and release of toxic anti-angiogenic factors", "Excessive estrogen production", "Autoimmune destruction of the kidneys"]', 1, 'The spiral arteries fail to dilate properly. The starving placenta releases factors (like sFlt-1) that severely damage the mother''s endothelial cells everywhere, causing leaky vessels (proteinuria/edema) and vasospasm (hypertension).'),
    (v_topic_id, '263. When does Preeclampsia become Eclampsia?', '["When blood pressure exceeds 180/110", "When the patient develops generalized tonic-clonic seizures", "When the patient starts bleeding", "When proteinuria exceeds 5g/day"]', 1, 'Eclampsia is defined by the onset of seizures (due to cerebral edema and vasospasm) in a patient with preeclampsia. It is a massive emergency.'),
    (v_topic_id, '264. What is the ultimate, definitive treatment for severe Preeclampsia / Eclampsia?', '["Antihypertensive drugs", "Magnesium sulfate", "Delivery of the fetus and placenta", "Strict bed rest"]', 2, 'Because the placenta is the source of the toxic factors driving the disease, delivering the placenta cures the condition.'),
    (v_topic_id, '265. What drug is given to women with severe preeclampsia specifically to PREVENT eclamptic seizures?', '["Phenytoin", "Diazepam", "Magnesium Sulfate (IV)", "Labetalol"]', 2, 'Magnesium sulfate is highly effective at stabilizing the CNS and preventing seizures. It is NOT given to lower blood pressure.'),
    (v_topic_id, '266. HELLP Syndrome is a severe variant of preeclampsia. What does HELLP stand for?', '["Hypertension, Edema, Low Leukocytes, Pain", "Hemolysis, Elevated Liver enzymes, Low Platelets", "Hemorrhage, Eclampsia, Lung Lesions, Proteinuria", "Hyperglycemia, Edema, Large Liver, Preeclampsia"]', 1, 'Endothelial damage causes microangiopathic hemolytic anemia (schistocytes). Fibrin clots consume platelets (thrombocytopenia). Liver sinusoids clot, causing necrosis (elevated AST/ALT).'),
    (v_topic_id, '267. Gestational Trophoblastic Disease involves abnormal proliferation of trophoblastic tissue. What defines a Complete Hydatidiform Mole?', '["Fertilization of an empty egg by one (or two) sperm; 46,XX or 46,XY; no fetal parts", "Fertilization of a normal egg by two sperm; 69,XXY; some fetal parts present", "A normal pregnancy that died early", "A tumor of the ovary"]', 0, 'The egg lacks maternal DNA. The sperm duplicates its own DNA. It is entirely PATERNAL. No fetus forms. The chorionic villi swell up into massive, grape-like fluid-filled vesicles.'),
    (v_topic_id, '268. What defines a Partial Hydatidiform Mole?', '["Empty egg + 1 sperm", "Fertilization of a normal egg (with maternal DNA) by TWO sperm (or one diploid sperm), resulting in a triploid (69,XXY) karyotype. Some fetal parts exist.", "No sperm involved", "Normal diploid karyotype"]', 1, 'Because maternal DNA is present, a partial, highly deformed fetus tries to form, but it is not viable. Only SOME villi are swollen.'),
    (v_topic_id, '269. How does a Complete Mole typically present clinically in the first trimester?', '["Severe vaginal bleeding, a uterus MUCH larger than expected for dates, and massively high hCG (>100,000)", "A uterus smaller than dates and low hCG", "Painless bleeding and normal hCG", "Ectopic pregnancy symptoms"]', 0, 'The rapidly proliferating trophoblasts secrete massive hCG, causing severe nausea/vomiting (hyperemesis gravidarum), large uterus, and sometimes early-onset preeclampsia (<20 weeks).'),
    (v_topic_id, '270. On ultrasound, what is the classic appearance of a Complete Mole?', '["A normal fetus with no fluid", "A ''snowstorm'' or ''cluster of grapes'' appearance", "A single large cyst", "An empty sac"]', 1, 'The "snowstorm" is the hundreds of swollen, hydropic chorionic villi filling the uterus.'),
    (v_topic_id, '271. Which type of mole (Complete or Partial) carries a much higher risk (15-20%) of progressing to malignant Choriocarcinoma?', '["Partial mole", "Complete mole", "They have equal risk", "Neither has any risk"]', 1, 'Complete moles have a significantly higher risk of malignant transformation. Patients must be monitored with serial hCG levels for 6-12 months after D&C removal to ensure no cancer develops.'),
    (v_topic_id, '272. Gestational Choriocarcinoma is a highly aggressive malignancy arising from the trophoblasts of a pregnancy (often a mole). How does it differ histologically from a normal mole?', '["It has larger villi", "It completely LACKS chorionic villi; it is just a solid mass of invasive syncytiotrophoblasts and cytotrophoblasts", "It contains fetal bone", "It contains maternal tissue"]', 1, 'Malignant choriocarcinoma loses the ability to form villous structures.'),
    (v_topic_id, '273. Where is the most common site of metastasis for Gestational Choriocarcinoma?', '["Brain", "Liver", "Lungs (causing hemoptysis and ''cannonball'' lesions on CXR)", "Bone"]', 2, 'Trophoblasts are designed to seek out and invade blood vessels. The tumor enters the uterine veins and travels directly to the lungs via the IVC.'),
    (v_topic_id, '274. Why is Gestational Choriocarcinoma considered one of the great successes of oncology?', '["It never metastasizes", "It has a near 100% cure rate with chemotherapy (e.g., Methotrexate) because it contains foreign paternal antigens", "It resolves on its own", "It can be cured with aspirin"]', 1, 'Because it arises from a pregnancy, it contains paternal DNA. The mother''s immune system views it as a foreign graft, helping the chemotherapy destroy it completely.'),

    -- BREAST CANCER ADDITIONS & MIXED REVIEW (275-300)
    (v_topic_id, '275. Which quadrant of the breast contains the highest concentration of glandular tissue and therefore the most carcinomas?', '["Upper outer quadrant", "Lower outer quadrant", "Upper inner quadrant", "Lower inner quadrant"]', 0, 'The upper outer quadrant (Tail of Spence) is the site of roughly 50% of all breast cancers.'),
    (v_topic_id, '276. A 28-year-old female notices a breast lump right before her period that is tender and seems to get smaller after menstruation. Diagnosis?', '["Fibroadenoma", "Fibrocystic change", "Breast cancer", "Intraductal papilloma"]', 1, 'Fibrocystic changes fluctuate wildly with the menstrual cycle due to hormonal changes.'),
    (v_topic_id, '277. A 22-year-old female finds a firm, rubbery, highly mobile, painless mass in her breast. It does not fluctuate with her period. Diagnosis?', '["Fibroadenoma", "Fibrocystic change", "Breast cancer", "Phyllodes tumor"]', 0, 'Fibroadenomas ("breast mice") are completely benign and highly mobile.'),
    (v_topic_id, '278. A patient has a biopsy showing "Apocrine Metaplasia" in her breast. What is her risk of developing breast cancer?', '["10x increased", "5x increased", "2x increased", "No increased risk"]', 3, 'Apocrine metaplasia is the ONLY form of fibrocystic change that carries absolutely zero increased risk of cancer.'),
    (v_topic_id, '279. Which histological feature defines "Sclerosing Adenosis" in the breast?', '["Large pools of mucin", "Increased number of compressed acini/glands in a fibrotic stroma with central calcifications", "Single file lines of cells", "Leaf-like projections"]', 1, 'It carries a 1.5 to 2x increased risk of cancer and mimics carcinoma on mammogram (calcifications) and palpation (hard mass).'),
    (v_topic_id, '280. A woman develops bloody nipple discharge. A small mass is resected from a major subareolar duct. It has both epithelial and myoepithelial cells lining fibrovascular cores. Diagnosis?', '["Papillary carcinoma", "Intraductal Papilloma", "DCIS", "Fibroadenoma"]', 1, 'The presence of the myoepithelial layer proves it is a benign papilloma. Malignant papillary carcinoma lacks this layer.'),
    (v_topic_id, '281. Invasive Lobular Carcinoma (ILC) lacks E-cadherin. What is a unique clinical feature of ILC regarding metastasis compared to Ductal Carcinoma?', '["It never metastasizes", "It has a strange propensity to metastasize to the CSF (carcinomatous meningitis), GI tract, and ovaries", "It only goes to the brain", "It only spreads via lymph"]', 1, 'While IDC typically goes to bone, lungs, and liver, ILC uniquely favors serosal surfaces, the GI tract, and the meninges.'),
    (v_topic_id, '282. Trastuzumab (Herceptin) is an amazing drug for HER2+ breast cancer. What is its most significant side effect?', '["Pulmonary fibrosis", "Cardiotoxicity (reversible heart failure / decreased ejection fraction)", "Renal failure", "Hemorrhagic cystitis"]', 1, 'Patients on Trastuzumab must have regular echocardiograms to monitor for heart failure, which is usually reversible if the drug is stopped.'),
    (v_topic_id, '283. Tamoxifen is a SERM used for ER+ breast cancer. It acts as an ANTAGONIST in the breast. How does it act in the uterus?', '["Antagonist", "Agonist (stimulating endometrial hyperplasia)", "It has no effect", "It causes atrophy"]', 1, 'This is its major risk: while it prevents breast cancer recurrence, it increases the risk of endometrial polyps and endometrial carcinoma.'),
    (v_topic_id, '284. Raloxifene is another SERM. How does its action profile differ from Tamoxifen?', '["It is an agonist in both breast and uterus", "It is an antagonist in the breast AND the uterus (no increased risk of endometrial cancer)", "It is an agonist in the breast", "It only works in males"]', 1, 'Raloxifene is an antagonist at the breast and uterus, but an agonist at the bone (used to treat osteoporosis). It does NOT cause endometrial cancer. ("Relax, Raloxifene is safe for the uterus").'),
    (v_topic_id, '285. Aromatase Inhibitors (like Anastrozole and Letrozole) are used for ER+ breast cancer. How do they work?', '["They block the estrogen receptor", "They block the peripheral conversion of androgens to estrogen in fat tissue, starving the tumor", "They destroy the ovaries", "They stimulate progesterone"]', 1, 'They are used primarily in postmenopausal women whose primary source of estrogen is peripheral fat conversion, not the ovaries.'),

    -- COMPREHENSIVE MIXED PATHOLOGY (286-320)
    (v_topic_id, '286. What is the classic triad of symptoms for an ectopic pregnancy?', '["Fever, chills, and vomiting", "Amenorrhea, followed by vaginal bleeding and lower abdominal pain", "Hypertension, proteinuria, and edema", "Weight loss, night sweats, and cough"]', 1, 'The patient misses a period (amenorrhea), then the tube begins to stretch and bleed.'),
    (v_topic_id, '287. Which hormone must you monitor to zero after removal of a Hydatidiform Mole?', '["FSH", "Estrogen", "Progesterone", "beta-hCG"]', 3, 'hCG must be monitored weekly to ensure no trophoblastic tissue remains. If it plateaus or rises, it indicates progression to invasive mole or choriocarcinoma.'),
    (v_topic_id, '288. Acute Mastitis is usually caused by S. aureus. What is the classic presentation of Inflammatory Breast Cancer that mimics it?', '["A swollen, red, warm, peau d''orange breast that DOES NOT respond to antibiotics", "A localized, fluctuant abscess with fever", "Clear nipple discharge", "A small, hard, painless lump"]', 0, 'Always suspect inflammatory carcinoma if "mastitis" fails to improve with antibiotics in a non-lactating woman.'),
    (v_topic_id, '289. Which ovarian tumor is classically associated with Call-Exner bodies?', '["Granulosa cell tumor", "Dysgerminoma", "Yolk sac tumor", "Sertoli-Leydig tumor"]', 0, 'Granulosa cell tumors secrete estrogen and feature Call-Exner bodies (rosettes).'),
    (v_topic_id, '290. Which ovarian tumor is classically associated with Reinke crystals?', '["Sertoli-Leydig cell tumor", "Fibroma", "Brenner tumor", "Mucinous cystadenoma"]', 0, 'Leydig cells produce androgens and contain Reinke crystals.'),
    (v_topic_id, '291. Which ovarian tumor is classically associated with Schiller-Duval bodies and elevated AFP?', '["Yolk sac (Endodermal sinus) tumor", "Dysgerminoma", "Teratoma", "Choriocarcinoma"]', 0, 'Yolk sac tumors are the most common in children and secrete AFP.'),
    (v_topic_id, '292. Which ovarian tumor is classically associated with Psammoma bodies?', '["Serous Cystadenocarcinoma", "Mucinous Cystadenocarcinoma", "Dysgerminoma", "Fibroma"]', 0, 'Serous carcinomas (Type II Endometrial and Serous Ovarian) calcify at the tips of their papillae.'),
    (v_topic_id, '293. Which tumor is associated with Meigs Syndrome (Ascites + Pleural effusion)?', '["Ovarian Fibroma", "Krukenberg tumor", "Granulosa cell tumor", "Choriocarcinoma"]', 0, 'Fibromas are benign, solid, white masses of fibroblasts.'),
    (v_topic_id, '294. A patient with a history of stomach cancer presents with bilateral solid ovarian masses. Histology shows signet ring cells. Diagnosis?', '["Krukenberg tumor", "Brenner tumor", "Dysgerminoma", "Endometrioma"]', 0, 'Metastasis of diffuse gastric cancer to bilateral ovaries.'),
    (v_topic_id, '295. Endometriosis most commonly affects the ovaries. What is the second most common site?', '["Uterine ligaments (causing pelvic pain/backache)", "Lungs", "Brain", "Spleen"]', 0, 'The uterosacral ligaments are frequently involved, causing deep pelvic pain and pain with intercourse (dyspareunia).'),
    (v_topic_id, '296. Adenomyosis is endometriosis within the myometrium. How is it definitively diagnosed?', '["Ultrasound", "MRI", "Histology after hysterectomy", "Blood test"]', 2, 'While MRI/Ultrasound can suspect it (globular, boggy uterus), definitive diagnosis requires microscopic examination of the hysterectomy specimen.'),
    (v_topic_id, '297. Which type of Endometrial Carcinoma (Type I or Type II) is driven by unopposed estrogen and arises from hyperplasia?', '["Type I (Endometrioid)", "Type II (Serous)", "Both", "Neither"]', 0, 'Type I is the classic "estrogen-driven" cancer in obese/nulliparous women.'),
    (v_topic_id, '298. Which genetic mutation is the hallmark of the highly aggressive Type II Serous Endometrial Carcinoma?', '["PTEN", "p53", "BRCA1", "APC"]', 1, 'p53 mutations are ubiquitous in Type II serous carcinomas, which arise from atrophic (not hyperplastic) endometrium.'),
    (v_topic_id, '299. Uterine Leiomyomas (fibroids) are extremely common. Do they transform into Leiomyosarcomas?', '["Yes, frequently", "No, Leiomyosarcomas arise de novo", "Only after menopause", "Only if they calcify"]', 1, 'Fibroids are benign and stay benign. Sarcomas are a separate, newly forming malignant entity.'),
    (v_topic_id, '300. DES (Diethylstilbestrol) exposure in utero causes which rare cancer in female offspring?', '["Clear cell adenocarcinoma of the vagina", "Squamous cell carcinoma of the cervix", "Endometrial carcinoma", "Ovarian fibroma"]', 0, 'DES causes vaginal adenosis, which transforms into clear cell adenocarcinoma.'),
    (v_topic_id, '301. HPV E6 inhibits which tumor suppressor?', '["Rb", "p53", "APC", "BRCA"]', 1, 'E6 = p53. E7 = Rb.'),
    (v_topic_id, '302. HPV E7 inhibits which tumor suppressor?', '["p53", "Rb (Retinoblastoma protein)", "PTEN", "WT1"]', 1, 'E7 binds Rb, releasing E2F to drive the cell cycle.'),
    (v_topic_id, '303. Which zone of the prostate is the primary site for Benign Prostatic Hyperplasia (BPH)?', '["Peripheral zone", "Transition (periurethral) zone", "Central zone", "Fibromuscular stroma"]', 1, 'Transition zone BPH pinches the urethra, causing urinary symptoms.'),
    (v_topic_id, '304. Which zone of the prostate is the primary site for Prostate Adenocarcinoma?', '["Transition zone", "Central zone", "Peripheral zone", "Anterior zone"]', 2, 'Peripheral zone (posteriorly). This is why DRE can palpate the rock-hard nodules.'),
    (v_topic_id, '305. A right-sided varicocele in an adult is a red flag for?', '["Renal Cell Carcinoma invading the IVC", "Prostate cancer", "Testicular torsion", "Epididymitis"]', 0, 'The right gonadal vein drains directly into the IVC. A right varicocele means the IVC is blocked, often by an RCC tumor thrombus.'),
    (v_topic_id, '306. Cryptorchidism increases the risk of which testicular tumor?', '["Leydig cell tumor", "Seminoma (Germ cell tumor)", "Lymphoma", "Sertoli cell tumor"]', 1, 'The undescended testicle has a much higher risk of germ cell tumors, even if surgically pulled down (orchiopexy).'),
    (v_topic_id, '307. Which testicular tumor is characterized by "fried egg" cells and a lymphocytic infiltrate?', '["Embryonal carcinoma", "Seminoma", "Yolk sac tumor", "Teratoma"]', 1, 'Seminoma is the male equivalent of the female dysgerminoma. Excellent prognosis, highly radiosensitive.'),
    (v_topic_id, '308. Which testicular tumor secretes massively high levels of hCG, causing hyperthyroidism and gynecomastia?', '["Seminoma", "Choriocarcinoma", "Yolk sac tumor", "Leydig cell tumor"]', 1, 'Choriocarcinoma mimics LH and TSH due to identical alpha-subunits.'),
    (v_topic_id, '309. Which vulvar lesion presents as thin, parchment-like skin and carries a slight risk of squamous cell carcinoma?', '["Lichen Simplex Chronicus", "Lichen Sclerosus", "Condyloma acuminatum", "Bartholin cyst"]', 1, 'Lichen sclerosus causes severe thinning and fibrosis.'),
    (v_topic_id, '310. Extramammary Paget Disease of the vulva vs. Melanoma: Which stains PAS positive?', '["Melanoma", "Extramammary Paget Disease", "Both", "Neither"]', 1, 'Paget cells are epithelial and mucin-producing (PAS+, Keratin+, S100-). Melanoma is (PAS-, Keratin-, S100+).'),
    (v_topic_id, '311. What is the defining histological feature of Embryonal Rhabdomyosarcoma (Sarcoma botryoides)?', '["Koilocytes", "Rhabdomyoblasts with cross-striations (Desmin positive)", "Clear cells", "Signet ring cells"]', 1, 'It is a malignant muscle tumor in young girls presenting as a grape-like vaginal mass.'),
    (v_topic_id, '312. What is the primary cause of Cervical Cancer?', '["Smoking", "Obesity", "Persistent infection with High-Risk HPV (16, 18)", "Genetics"]', 2, 'HPV is the necessary cause of nearly 100% of cervical squamous cell carcinomas.'),
    (v_topic_id, '313. How does advanced Cervical Cancer typically cause death?', '["Brain mets", "Direct invasion into the bladder, blocking ureters and causing renal failure", "Liver failure", "Heart failure"]', 1, 'Local invasion causes bilateral hydronephrosis and uremia.'),
    (v_topic_id, '314. Which form of DCIS is the most aggressive and features central "cheese-like" necrosis?', '["Papillary", "Cribriform", "Comedocarcinoma", "Solid"]', 2, 'Comedo DCIS calcifies heavily and is highly aggressive.'),
    (v_topic_id, '315. Paget Disease of the Breast is almost 100% associated with?', '["An underlying invasive carcinoma or DCIS in the breast", "No underlying cancer", "Ovarian cancer", "Melanoma"]', 0, 'The malignant cells migrate from the ducts up into the nipple skin.'),
    (v_topic_id, '316. Which breast cancer subtype lacks E-cadherin and marches through the stroma in "single-file" lines?', '["Invasive Ductal Carcinoma", "Invasive Lobular Carcinoma", "Medullary Carcinoma", "Tubular Carcinoma"]', 1, 'ILC cells cannot stick together. Often bilateral and stealthy.'),
    (v_topic_id, '317. Which triple-negative breast cancer subtype paradoxically has a good prognosis due to a massive lymphocytic immune response?', '["Inflammatory carcinoma", "Medullary Carcinoma", "Comedocarcinoma", "Invasive lobular carcinoma"]', 1, 'Medullary carcinoma is heavily infiltrated by lymphocytes and associated with BRCA1.'),
    (v_topic_id, '318. Placental Abruption vs. Placenta Previa: Which one causes PAINFUL bleeding?', '["Placenta Previa", "Placental Abruption", "Both", "Neither"]', 1, 'Abruption involves tearing away of the placenta, causing severe pain and rigid abdomen. Previa is painless bleeding.'),
    (v_topic_id, '319. Preeclampsia is Hypertension + Proteinuria. What is Eclampsia?', '["Hypertension + Proteinuria + Seizures", "Hypertension + Proteinuria + Liver failure", "Hypertension + Proteinuria + Bleeding", "Hypertension + Edema"]', 0, 'Seizures define Eclampsia. Treat with Magnesium Sulfate and delivery.'),
